args.command:
$base='http://127.0.0.1:8787'

# 等无人机完成侦察（progress .07/s，需约15秒）
Write-Host 'waiting for drone route discovery...'
$done = $false
for ($i = 0; $i -lt 20; $i++) {
  Start-Sleep -Seconds 1
  $s = Invoke-RestMethod -Uri "$base/api/state" -Method Get
  if ($s.state.route.known) { $done = $true; break }
}
if ($done) {
  Write-Host 'route known, drone status:' $s.state.drone.status
  # 派遣救援车
  $res = Invoke-RestMethod -Uri "$base/api/tool" -Method Post -ContentType 'application/json' -Body '{"name":"dispatch_rescue_vehicle"}'
  Write-Host 'dispatch_rescue phase:' $res.state.phase 'status:' $res.state.rescueVehicle.status
} else {
  Write-Host 'drone did not finish in time, status:' $s.state.drone.status
}

