// 执行一次基础决策：调用 decide 判断，若产生可执行工具则记录 agentic 决策事件并执行。
// 返回 { decision, executed? , toolResult? }。观察类工具不计入动作，仅作为决策证据。
function runAgentDecision() {
  const decision = decide(state, true);
  const { step, name, tool, cameraId, reason, blocked, done, act } = decision;
  if (done) {
    event('agh','decision',`[步骤${step}] ${name}：${reason}`,{step,tool:null});
    return { decision, executed: null };
  }
  if (blocked) {
    event('agh','blocked',`[步骤${step}] ${name}：${reason}`,{step,tool});
    return { decision, executed: null };
  }
  if (!tool) {
    event('agh','decision',`[步骤${step}] ${name}：${reason}`,{step,tool:null});
    return { decision, executed: null };
  }
  // 观察类：纯读取，作为决策证据记录
  if (observeTools.includes(tool)) {
    let obsData;
    try { obsData = action(tool,'agh', cameraId ? { cameraId } : {} ).data; }
    catch(e) { obsData = { error: e.message }; }
    event('agh','observe',`[步骤${step}] ${name}：${reason} → 观测${cameraId?' '+cameraId:''}`,{step,tool,cameraId,data:obsData});
    state.connection.lastAgentEvent = new Date().toISOString();
    return { decision, executed: { tool, result: obsData } };
  }
  // 动作类：执行工具
  try {
    const tr = action(tool,'agh', cameraId ? { cameraId } : {});
    event('agh','decision',`[步骤${step}] ${name}：${reason} → 已执行 ${tool}`,{step,tool});
    return { decision, executed: { tool, result: tr } };
  } catch(e) {
    state.metrics.failedToolCalls++;
    event('agh','rejected',`[步骤${step}] ${name}：${reason} → ${tool} 被拒（${e.message}）`,{step,tool});
    return { decision, executed: { tool, error: e.message } };
  }
}
