const base='http://127.0.0.1:8787';
(async()=>{
  // 端点健康检查
  const html=await(await fetch(base+'/')).text();
  console.log('GET / :', html.includes('基础决策')?'OK (含基础决策按钮)':'(旧页面, 需刷新浏览器)');
  const plan=await(await fetch(base+'/api/agent/plan')).json();
  console.log('GET /api/agent/plan steps:', plan.plan.length, '| routeReady:', plan.routeReady, '| phase:', plan.phase);
  const as=await(await fetch(base+'/api/agent/state')).json();
  console.log('GET /api/agent/state currentStep:', as.currentStep, as.decision.name);
  // 完整链路
  await fetch(base+'/api/control',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({reset:true})});
  let done=0, blockedSeen=false;
  for(let i=0;i<70;i++){
    const r=await fetch(base+'/api/agent/decide',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});
