    if(d.state.phase==='completed'){done=1;console.log('COMPLETED at T'+i);break;}
    await new Promise(res=>setTimeout(res,1000));
  }
  const st=await(await fetch(base+'/api/state')).json();
  console.log('success:',st.state.metrics.success,'| agentToolCalls:',st.state.metrics.agentToolCalls,'| failed:',st.state.metrics.failedToolCalls);
  console.log('vms:',st.state.vms.message,'| light:',st.state.light.on,'| route known:',st.state.route.known);
  const ag=await(await fetch(base+'/api/agent/state')).json();
  console.log('total decision events:',ag.decisionEvents.length);
  // 验证 12 步都出现过
  const steps=ag.decisionEvents.map(e=>parseInt((e.message.match(/步骤(\d)/)||[])[1]||0));
  const present=[3,4,6,7,9,10,11,12].filter(s=>steps.includes(s));
