content.text:
1	// agent.mjs — 基础决策顺序引擎（C 的 AGH 接入前，由仿真驱动演示）
2	// 导出 DECISION_PLAN（12 步声明）与 decide(state, apply) 判定器。
3	// 每步返回 { step, kind: observe|judge|act, action?, reason }，由调用方执行/记录。
4	
5	const limits = {
6	  selfRecovery: { minVisibility: 150 },
7	  drone: { maxWind: 12, minVisibility: 150, minBattery: 20 },
8	  rescue: { minVisibility: 100 },
9	};
10	
11	// 路线是否已确认可通行
12	export const routeReady = (s) => Boolean(s.route.known && s.route.traversable);
13	
14	// 12 步基础决策顺序（顺序即任务推进序）
15	export const DECISION_PLAN = [
16	  { step: 1, name: '读取气象站状态', kind: 'observe', tool: 'get_weather_station_status' },
17	  { step: 2, name: '读取车辆状态', kind: 'observe', tool: 'get_vehicle_status' },
18	  { step: 3, name: '判断车辆能否自救', kind: 'judge', tool: 'attempt_self_recovery' },
19	  { step: 4, name: '必要时停止车辆', kind: 'act', tool: 'stop_vehicle' },
20	  { step: 5, name: '判断无人机能否起飞', kind: 'judge', tool: 'dispatch_drone' },
21	  { step: 6, name: '派遣无人机侦察', kind: 'act', tool: 'dispatch_drone' },
22	  { step: 7, name: '读取无人机摄像头', kind: 'observe', tool: 'get_camera_frame' },
23	  { step: 8, name: '确认备用路线', kind: 'judge', tool: 'return_drone' },
24	  { step: 9, name: '设置补光灯与诱导屏', kind: 'act', tool: 'turn_light_on' },
25	  { step: 10, name: '派遣救援车', kind: 'act', tool: 'dispatch_rescue_vehicle' },
26	  { step: 11, name: '读取救援车摄像头', kind: 'observe', tool: 'get_camera_frame' },
27	  { step: 12, name: '完成牵引', kind: 'observe', tool: 'get_camera_frame' },
28	];
29	
30	// decide：给定当前快照，返回本轮该执行的“下一个有意义动作”。
31	// 规则：
32	//  - observe 步：恒可推进（纯读取），返回其工具名。
33	//  - judge 步（自救/无人机）：不满足安全阈值时记录为“未执行·原因”（退避），不抛错。
34	//  - act 步：满足条件才执行；不满足则跳过（返回下一步）。
35	// apply=false 时只返回建议不副作用；apply=true 由调用方执行 tool。
36	export function decide(state, apply = false) {
37	  const { weather: w, vehicle: v, drone: d, rescueVehicle: r } = state;
38	
39	  // 已完成则返回终态
40	  if (state.phase === 'completed') {
41	    return { step: 12, name: '完成牵引', done: true, reason: '车辆已安全转移，任务完成。', tool: null };
42	  }
43	
44	  // Step 3 判断自救
45	  const canSelf = v.stuck && w.visibility >= limits.selfRecovery.minVisibility;
46	  // Step 4 需要停止：车辆仍卡住且正在尝试自救（自救结束后仍卡住 → 停机再走无人机）
47	  // Step 5/6 判断/派遣无人机
48	  const droneOk = w.windSpeed <= limits.drone.maxWind && w.visibility >= limits.drone.minVisibility && d.battery >= limits.drone.minBattery;
49	  const rescueOk = w.visibility >= limits.rescue.minVisibility;
50	
51	  // 推进逻辑（按当前 phase 与设备态决定当前该落在哪一步）
52	  if (state.phase === 'waiting' && v.stuck) {
53	    // 3. 判断自救
54	    if (canSelf && v.status === 'stuck' && !v.actionTime) {
55	      return apply ? { step: 3, name: '判断车辆能否自救', act: true, tool: 'attempt_self_recovery', reason: '能见度 ' + w.visibility + 'm≥150，尝试自救。' }
56	                 : { step: 3, name: '判断车辆能否自救', tool: 'attempt_self_recovery', reason: '能见度 ' + w.visibility + 'm≥150，应尝试自救。' };
57	    }
58	    // 自救不可行 → 4. 停止车辆（仅在仍卡住时）
59	    if (!canSelf && v.stuck && v.status === 'stuck') {
60	      return apply ? { step: 4, name: '必要时停止车辆', act: true, tool: 'stop_vehicle', reason: '能见度 ' + w.visibility + 'm<150，禁止自救，先停止车辆。' }
61	                 : { step: 4, name: '必要时停止车辆', tool: 'stop_vehicle', reason: '能见度不足，先停止车辆。' };
62	    }
63	  }
64	
65	  // 5/6 无人机判断与派遣（路线未知时）
66	  if (!routeReady(state)) {
67	    if (d.status === 'standby') {
68	      if (droneOk) {
69	        return apply ? { step: 6, name: '派遣无人机侦察', act: true, tool: 'dispatch_drone', reason: '风速 ' + w.windSpeed + 'm/s、能见度 ' + w.visibility + 'm，允许起飞侦察。' }
70	                   : { step: 6, name: '派遣无人机侦察', tool: 'dispatch_drone', reason: '天气允许，应派遣无人机。' };
71	      }
72	      // 天气不允许：记录退避
73	      return { step: 5, name: '判断无人机能否起飞', tool: null, blocked: true,
74	               reason: '风速 ' + w.windSpeed + 'm/s 或能见度 ' + w.visibility + 'm 超出无人机安全阈值，暂不允许起飞（等待天气）。' };
75	    }
76	    // 无人机在飞（scouting）→ 7. 读摄像头
77	    if (d.status === 'scouting') {
78	      return { step: 7, name: '读取无人机摄像头', tool: 'get_camera_frame', cameraId: d.camId,
79	               reason: '无人机侦察中（progress ' + Math.round(d.progress * 100) + '%），读取 ' + d.camId + ' 观测路线。' };
80	    }
81	    // 8. 确认备用路线（侦察完成）
82	    if (routeReady(state)) {
83	      return { step: 8, name: '确认备用路线', tool: null, reason: '无人机已确认 ' + state.route.name + ' 可通行。' };
84	    }
85	  }
86	
87	  // 路线已确认 → 9. 补光 + 诱导屏
88	  if (routeReady(state) && r.status === 'standby') {
89	    if (!state.light.on || !state.vms.message) {
90	      // 主动作：开补光灯；伴随动作：设诱导屏消息与限速
91	      const extra = [
92	        { tool: 'set_message', deviceId: state.vms.id, message: '前方沙尘 注意减速' },
93	        { tool: 'set_speed_limit', deviceId: state.vms.id, limit: 40 },
94	      ];
95	      return apply
96	        ? { step: 9, name: '设置补光灯与诱导屏', act: true, tool: 'turn_light_on', brightness: 100, extra, reason: '路线已确认，开启补光灯并设诱导屏（限速 40）。' }
97	        : { step: 9, name: '设置补光灯与诱导屏', tool: 'turn_light_on', extra, reason: '路线已确认，应开启补光灯并设诱导屏。' };
98	    }
99	    // 10. 派遣救援车
100	    if (rescueOk) {
101	      return apply ? { step: 10, name: '派遣救援车', act: true, tool: 'dispatch_rescue_vehicle', reason: '能见度 ' + w.visibility + 'm≥100，派遣救援车沿确认路线牵引。' }
102	                 : { step: 10, name: '派遣救援车', tool: 'dispatch_rescue_vehicle', reason: '能见度允许，应派遣救援车。' };
103	    }
104	    return { step: 10, name: '派遣救援车', tool: null, blocked: true,
105	             reason: '能见度 ' + w.visibility + 'm<100，救援车暂缓派遣，等待天气恢复。' };
106	  }
107	
108	  // 救援车在动 → 11. 读救援摄像头
109	  if (r.status === 'enroute' || r.status === 'paused' || r.status === 'towing') {
110	    if (r.status === 'towing') {
111	      // 12. 完成牵引
112	      return { step: 12, name: '完成牵引', tool: 'get_camera_frame', cameraId: r.camId, reason: '救援车正在牵引被困车辆（tow ' + r.towTime + '/8）。' };
113	    }
114	    return { step: 11, name: '读取救援车摄像头', tool: 'get_camera_frame', cameraId: r.camId,
115	             reason: '救援车' + (r.status === 'enroute' ? '行驶中（' + Math.round(r.progress * 100) + '%）' : '等待天气') + '，读取 ' + r.camId + '。' };
116	  }
117	
118	  // 兜底
119	  return { step: state.phase === 'completed' ? 12 : 9, name: '等待', tool: null, reason: '等待下一可行动作。' };
120	}

args.content:
// agent.mjs — 基础决策顺序引擎 + 动态变化响应（C 的 AGH 接入前，由仿真驱动演示）
// 导出 DECISION_PLAN（12 步声明）与 decide(state, apply) 判定器。
// 每步返回 { step, kind: observe|judge|act, tool?, extra?, blocked?, done?, reason }。

const limits = {
  selfRecovery: { minVisibility: 150 },
  drone: { maxWind: 12, minVisibility: 150, minBattery: 20 },
  rescue: { minVisibility: 100 },
};

// 路线是否已确认可通行
export const routeReady = (s) => Boolean(s.route.known && s.route.traversable);
// 路线是否"已知但不可通行"（触发封闭绕行）
export const routeBlocked = (s) => Boolean(s.route.known && !s.route.traversable);

// 12 步基础决策顺序（顺序即任务推进序）
export const DECISION_PLAN = [
  { step: 1, name: '读取气象站状态', kind: 'observe', tool: 'get_weather_station_status' },
  { step: 2, name: '读取车辆状态', kind: 'observe', tool: 'get_vehicle_status' },
  { step: 3, name: '判断车辆能否自救', kind: 'judge', tool: 'attempt_self_recovery' },
  { step: 4, name: '必要时停止车辆', kind: 'act', tool: 'stop_vehicle' },
  { step: 5, name: '判断无人机能否起飞', kind: 'judge', tool: 'dispatch_drone' },
  { step: 6, name: '派遣无人机侦察', kind: 'act', tool: 'dispatch_drone' },
  { step: 7, name: '读取无人机摄像头', kind: 'observe', tool: 'get_camera_frame' },
  { step: 8, name: '确认备用路线', kind: 'judge', tool: 'return_drone' },
  { step: 9, name: '设置补光灯与诱导屏', kind: 'act', tool: 'turn_light_on' },
  { step: 10, name: '派遣救援车', kind: 'act', tool: 'dispatch_rescue_vehicle' },
  { step: 11, name: '读取救援车摄像头', kind: 'observe', tool: 'get_camera_frame' },
  { step: 12, name: '完成牵引', kind: 'observe', tool: 'get_camera_frame' },
];

// 诱导屏文案随情境选择
const VMS = {
  rescueDispatch: { message: '前方救援，限速 30', limit: 30 },
  closedDetour: { message: '前方封闭，请绕行', limit: null },
  sandstorm: { message: '前方沙尘 注意减速', limit: 40 },
};

// decide：给定当前快照，返回本轮该执行的"下一个有意义动作"。
export function decide(state, apply = false) {
  const { weather: w, vehicle: v, drone: d, rescueVehicle: r } = state;
  const vmsId = state.vms.id;

  if (state.phase === 'completed') {
    return { step: 12, name: '完成牵引', done: true, reason: '车辆已安全转移，任务完成。', tool: null };
  }

  const canSelf = v.stuck && w.visibility >= limits.selfRecovery.minVisibility;
  const droneOk = w.windSpeed <= limits.drone.maxWind && w.visibility >= limits.drone.minVisibility && d.battery >= limits.drone.minBattery;
  const rescueOk = w.visibility >= limits.rescue.minVisibility;
  const lowVisibility = w.visibility < limits.rescue.minVisibility; // <100m 需补光

  // 动态响应 A：能见度过低 → 打开补光灯（无论处于哪一阶段，只要救援未结束且灯未开）
  if (lowVisibility && !state.light.on && !routeBlocked(state)) {
    return apply
      ? { step: 9, name: '设置补光灯与诱导屏', act: true, tool: 'turn_light_on', brightness: 100,
          extra: [{ tool: 'set_message', deviceId: vmsId, message: VMS.sandstorm.message },
                  { tool: 'set_speed_limit', deviceId: vmsId, limit: VMS.sandstorm.limit }],
          reason: '能见度 ' + w.visibility + 'm<100，打开补光灯并提示注意减速。' }
      : { step: 9, name: '设置补光灯与诱导屏', tool: 'turn_light_on',
          extra: [{ tool: 'set_message', deviceId: vmsId, message: VMS.sandstorm.message },
                  { tool: 'set_speed_limit', deviceId: vmsId, limit: VMS.sandstorm.limit }],
          reason: '能见度 ' + w.visibility + 'm<100，应打开补光灯。' };
  }

  // 动态响应 B：路线不可通行 → 诱导屏显示"前方封闭，请绕行"
  if (routeBlocked(state)) {
    const want = VMS.closedDetour.message;
    const already = state.vms.message === want;
    if (!already) {
      return apply
        ? { step: 9, name: '设置补光灯与诱导屏', act: true, tool: 'turn_light_on', brightness: 100,
            extra: [{ tool: 'set_message', deviceId: vmsId, message: want }],
            reason: '备用路线不可通行，诱导屏改为"前方封闭，请绕行"。' }
        : { step: 9, name: '设置补光灯与诱导屏', tool: 'turn_light_on',
            extra: [{ tool: 'set_message', deviceId: vmsId, message: want }],
            reason: '路线不可通行，应显示绕行提示。' };
    }
    // 已显示绕行 → 任务无法按原路线推进，退避等待重新侦察
    return { step: 8, name: '确认备用路线', tool: null, blocked: true,
             reason: '备用路线不可通行，已指示绕行，需重新侦察或等待路线恢复。' };
  }

  // 推进逻辑
  if (state.phase === 'waiting' && v.stuck) {
    // 3. 判断自救
    if (canSelf && v.status === 'stuck' && !v.actionTime) {
      return apply ? { step: 3, name: '判断车辆能否自救', act: true, tool: 'attempt_self_recovery', reason: '能见度 ' + w.visibility + 'm≥150，尝试自救。' }
                 : { step: 3, name: '判断车辆能否自救', tool: 'attempt_self_recovery', reason: '能见度 ' + w.visibility + 'm≥150，应尝试自救。' };
    }
    // 自救不可行 → 4. 停止车辆
    if (!canSelf && v.stuck && v.status === 'stuck') {
      return apply ? { step: 4, name: '必要时停止车辆', act: true, tool: 'stop_vehicle', reason: '能见度 ' + w.visibility + 'm<150，禁止自救，先停止车辆。' }
                 : { step: 4, name: '必要时停止车辆', tool: 'stop_vehicle', reason: '能见度不足，先停止车辆。' };
    }
  }

  // 5/6 无人机判断与派遣（路线未知时）
  if (!routeReady(state)) {
    if (d.status === 'standby') {
      if (droneOk) {
        return apply ? { step: 6, name: '派遣无人机侦察', act: true, tool: 'dispatch_drone', reason: '风速 ' + w.windSpeed + 'm/s、能见度 ' + w.visibility + 'm，允许起飞侦察。' }
                   : { step: 6, name: '派遣无人机侦察', tool: 'dispatch_drone', reason: '天气允许，应派遣无人机。' };
      }
      // 动态响应 C：风速过高 / 能见度低 → 无人机不能起飞，等待天气改善
      const windHigh = w.windSpeed > limits.drone.maxWind;
      const visLow = w.visibility < limits.drone.minVisibility;
      const cause = windHigh && visLow ? '风速过高且能见度过低'
                : windHigh ? '风速 ' + w.windSpeed + 'm/s>12m/s'
                : '能见度 ' + w.visibility + 'm<150m';
      return { step: 5, name: '判断无人机能否起飞', tool: null, blocked: true, waiting: 'weather',
               reason: cause + '，无人机暂缓起飞（等待天气改善）。' };
    }
    // 无人机在飞（scouting）→ 7. 读摄像头
    if (d.status === 'scouting') {
      return { step: 7, name: '读取无人机摄像头', tool: 'get_camera_frame', cameraId: d.camId,
               reason: '无人机侦察中（progress ' + Math.round(d.progress * 100) + '%），读取 ' + d.camId + ' 观测路线。' };
    }
    // 8. 确认备用路线（侦察完成）
    if (routeReady(state)) {
      return { step: 8, name: '确认备用路线', tool: null, reason: '无人机已确认 ' + state.route.name + ' 可通行。' };
    }
  }

  // 路线已确认 → 10. 派遣救援车（出发前诱导屏显示"前方救援，限速 30"）
  if (routeReady(state) && r.status === 'standby') {
    // 动态响应 D：救援车出发 → 诱导屏显示"前方救援，限速 30"
    const want = VMS.rescueDispatch.message;
    if (rescueOk && state.vms.message !== want) {
      return apply
        ? { step: 9, name: '设置补光灯与诱导屏', act: true, tool: 'turn_light_on', brightness: 100,
            extra: [{ tool: 'set_message', deviceId: vmsId, message: want },
                    { tool: 'set_speed_limit', deviceId: vmsId, limit: VMS.rescueDispatch.limit }],
            reason: '救援车即将出发，诱导屏改为"前方救援，限速 30"。' }
        : { step: 9, name: '设置补光灯与诱导屏', tool: 'turn_light_on',
            extra: [{ tool: 'set_message', deviceId: vmsId, message: want },
                    { tool: 'set_speed_limit', deviceId: vmsId, limit: VMS.rescueDispatch.limit }],
            reason: '救援车即将出发，应显示限速 30 提示。' };
    }
    if (rescueOk) {
      return apply ? { step: 10, name: '派遣救援车', act: true, tool: 'dispatch_rescue_vehicle', reason: '能见度 ' + w.visibility + 'm≥100，派遣救援车沿确认路线牵引。' }
                 : { step: 10, name: '派遣救援车', tool: 'dispatch_rescue_vehicle', reason: '能见度允许，应派遣救援车。' };
    }
    return { step: 10, name: '派遣救援车', tool: null, blocked: true, waiting: 'weather',
             reason: '能见度 ' + w.visibility + 'm<100，救援车暂缓派遣，等待天气恢复。' };
  }

  // 救援车在动 → 11. 读救援摄像头
  if (r.status === 'enroute' || r.status === 'paused' || r.status === 'towing') {
    if (r.status === 'towing') {
      return { step: 12, name: '完成牵引', tool: 'get_camera_frame', cameraId: r.camId, reason: '救援车正在牵引被困车辆（tow ' + r.towTime + '/8）。' };
    }
    return { step: 11, name: '读取救援车摄像头', tool: 'get_camera_frame', cameraId: r.camId,
             reason: '救援车' + (r.status === 'enroute' ? '行驶中（' + Math.round(r.progress * 100) + '%）' : '等待天气') + '，读取 ' + r.camId + '。' };
  }

  // 兜底
  return { step: 9, name: '等待', tool: null, reason: '等待下一可行动作。' };
}

