const fs = require('fs');
const p = 'C:\\Users\\oyfsh\\Downloads\\沙尘救援3.zip\\沙尘救援3.zip\\沙尘救援3\\server.mjs';
let t = fs.readFileSync(p, 'utf8');

if (t.includes('body.route && typeof body.route')) {
  console.log('route control already present');
  process.exit(0);
}

const marker = "      else if ('autoWeather' in body) state.autoWeather=Boolean(body.autoWeather);";
if (!t.includes(marker)) { console.log('marker not found'); process.exit(1); }

const insert = marker + "\n      else if (body.route && typeof body.route === 'object') { const tr=body.route.traversable; state.route={ ...state.route, known:body.route.known !== undefined?Boolean(body.route.known):state.route.known, traversable:tr !== undefined?Boolean(tr):state.route.traversable, inspectedAt:new Date().toISOString(), name:state.route.name || '北侧硬质路肩' }; event('manual','route','人工设置路线状态：known='+state.route.known+'，traversable='+state.route.traversable+'。'); }";

t = t.replace(marker, insert);
fs.writeFileSync(p, t);
console.log('inserted route control into /api/control');

// 动态场景测试脚本：对 4 类动态变化逐场景断言
// 依赖服务运行于 127.0.0.1:8787（start.cmd 已启动）
const base = 'http://127.0.0.1:8787';
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

let passed = 0, failed = 0;
function assert(cond, msg) {
  if (cond) { passed++; console.log('  PASS  ' + msg); }
  else { failed++; console.log('  FAIL  ' + msg); }
}
async function post(path, body) {
  const r = await fetch(base + path, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body || {}),
  });
  return { status: r.status, data: await r.json() };
}
// 执行一次 agent 决策并返回
async function decide() {
  return (await post('/api/agent/decide')).data;
}
// 反复 decide 直到满足 predicate 或超时
async function decideUntil(pred, timeoutMs = 8000) {
  const t0 = Date.now();
  let last = null;
  while (Date.now() - t0 < timeoutMs) {
    last = await decide();
    if (pred(last)) return last;
    await sleep(1000);
  }
  return last;
}

(async () => {
  console.log('=== 场景 C：风速过高 → 无人机不能起飞 → 等待天气改善 ===');
  await post('/api/control', { reset: true });
  await post('/api/control', { level: 6 }); // windSpeed≈16.8, visibility≈19
  let d = await decide();
  assert(d.decision.step === 5 && d.decision.blocked && d.decision.waiting === 'weather',
    '等级6（风速16.8）无人机被阻塞，step=' + d.decision.step + ' reason=' + d.decision.reason);
  // 降回等级2，天气改善，无人机应允许起飞
  await post('/api/control', { level: 2 });
  d = await decideUntil((x) => x.decision.act === true || (x.decision.blocked && x.decision.waiting !== 'weather'), 10000);
  assert(d.decision.tool === 'dispatch_drone',
    '降回等级2后天气改善，无人机允许起飞（act=' + d.decision.act + ' tool=' + d.decision.tool + '）');

  console.log('\n=== 场景 B：能见度过低 → 打开补光灯 ===');
  await post('/api/control', { reset: true });
  await post('/api/control', { level: 4 }); // visibility≈68 <100
  let sb = await decideUntil((x) => x.state.light.on === true, 10000);
  assert(sb.state.light.on === true, '能见度<100（等级4≈68m）补光灯已开启');
  assert(sb.state.vms.message === '前方沙尘 注意减速', '诱导屏提示注意减速："' + sb.state.vms.message + '"');

  console.log('\n=== 场景 D：救援车出发 → 诱导屏显示"前方救援，限速 30" ===');
  await post('/api/control', { reset: true });
  await post('/api/control', { level: 2 });
  await post('/api/control', { route: { known: true, traversable: true } });
  let sd = await decideUntil((x) => x.state.vms.message === '前方救援，限速 30', 10000);
  assert(sd.state.vms.message === '前方救援，限速 30', '救援车出发前诱导屏改为"前方救援，限速 30"');
  sd = await decideUntil((x) => x.state.rescueVehicle.status === 'enroute' || x.state.rescueVehicle.status === 'towing', 10000);
  assert(sd.state.rescueVehicle.status === 'enroute' || sd.state.rescueVehicle.status === 'towing',
    '救援车已出发（status=' + sd.state.rescueVehicle.status + '）');

  console.log('\n=== 场景 A：路线不可通行 → 诱导屏显示"前方封闭，请绕行" ===');
  await post('/api/control', { reset: true });
  await post('/api/control', { level: 2 });
  await post('/api/control', { route: { known: true, traversable: false } });
  let sa = await decideUntil((x) => x.state.vms.message === '前方封闭，请绕行', 10000);
  assert(sa.state.vms.message === '前方封闭，请绕行', '路线不可通行，诱导屏改为"前方封闭，请绕行"');
  assert(sa.decision.blocked === true && sa.decision.step === 8,
    '任务退避在 step8 等待重新侦察（blocked=' + sa.decision.blocked + '）');

  console.log('\n=== 汇总 ===');
  console.log('通过 ' + passed + ' / 失败 ' + failed);
  process.exit(failed ? 1 : 0);
})().catch((e) => {
  console.error('test error:', e);
  process.exit(2);
});

