(async () => {
  console.log('=== 场景 C：风速过高 → 无人机不能起飞 → 等待天气改善 ===');
  await post('/api/control', { reset: true });
  await post('/api/control', { level: 6 }); // windSpeed≈16.8, visibility≈19
  let d = await decide();
  assert(d.decision.step === 5 && d.decision.blocked && d.decision.waiting === 'weather',
    '等级6（风速16.8）无人机被阻塞，step=' + d.decision.step + ' reason=' + d.decision.reason);
  // 降回等级2，天气改善（vis≈383/wind≈9.6），决策应不再被天气阻塞
  await post('/api/control', { level: 2 });
  d = await decideUntil((x) => !x.decision.blocked || x.decision.waiting !== 'weather', 10000);
  assert(!d.decision.blocked || d.decision.waiting !== 'weather',
    '降回等级2后天气改善，决策恢复推进（step=' + d.decision.step + ' act=' + d.decision.act + ' tool=' + d.decision.tool + '）');

  console.log('\n=== 场景 B：能见度过低 → 打开补光灯 ===');
  await post('/api/control', { reset: true });
  await post('/api/control', { level: 4 }); // visibility≈68 <100
  await post('/api/control', { route: { known: true, traversable: true } }); // 进入救援准备阶段
  let sb = await decideUntil((x) => x.state.light.on === true, 10000);
  assert(sb.state.light.on === true, '能见度<100（等级4≈68m）补光灯已开启');
  assert(sb.state.vms.message === '前方沙尘 注意减速', '诱导屏提示注意减速："' + sb.state.vms.message + '"');

  console.log('\n=== 场景 D：救援车出发 → 诱导屏显示"前方救援，限速 30" ===');
  await post('/api/control', { reset: true });
  await post('/api/control', { level: 2 });
  await post('/api/control', { route: { known: true, traversable: true } });
  let sd = await decideUntil((x) => x.state.vms.message === '前方救援，限速 30', 10000);
  assert(sd.state.vms.message === '前方救援，限速 30', '救援车出发前诱导屏改为"前方救援，限速 30"');
  sd = await decideUntil((x) => x.state.rescueVehicle.status === 'enroute' || x.state.rescueVehicle.status === 'towing', 10000);
  assert(sd.state.rescueVehicle.status === 'enroute' || sd.state.rescueVehicle.status === 'towing',
    '救援车已出发（status=' + sd.state.rescueVehicle.status + '）');

  console.log('\n=== 场景 A：路线不可通行 → 诱导屏显示"前方封闭，请绕行" ===');
  await post('/api/control', { reset: true });
  await post('/api/control', { level: 2 });
  await post('/api/control', { route: { known: true, traversable: false } });
  let sa = await decideUntil((x) => x.state.vms.message === '前方封闭，请绕行', 10000);
  assert(sa.state.vms.message === '前方封闭，请绕行', '路线不可通行，诱导屏改为"前方封闭，请绕行"');
  sa = await decide();
  assert(sa.decision.blocked === true && sa.decision.step === 8,
    '任务退避在 step8 等待重新侦察（blocked=' + sa.decision.blocked + ' step=' + sa.decision.step + '）');

  console.log('\n=== 汇总 ===');
  console.log('通过 ' + passed + ' / 失败 ' + failed);
  process.exit(failed ? 1 : 0);
})().catch((e) => {
  console.error('test error:', e);
  process.exit(2);
});

