// runner.js — 启动 server（detached）并运行 test_dynamic.js，完成后清理
const { spawn, execFileSync } = require('child_process');
const path = require('path');
const dir = 'C:\\Users\\oyfsh\\Downloads\\沙尘救援3.zip\\沙尘救援3.zip\\沙尘救援3';

// 清理旧监听
const { execSync } = require('child_process');
try {
  const out = execSync('netstat -ano | findstr :8787 | findstr LISTENING', { encoding: 'utf8' });
  const pids = [...new Set(out.trim().split(/\s+/).filter(Boolean))]
    .map((l) => l.split(/\s+/).pop())
    .filter((x) => /^\d+$/.test(x));
  pids.forEach((pid) => { try { execSync('taskkill /F /PID ' + pid, { stdio: 'ignore' }); } catch (e) {} });
} catch (e) {}

const server = spawn('node', [path.join(dir, 'server.mjs')], { detached: true, stdio: ['ignore', 'pipe', 'pipe'], cwd: dir });
server.stdout.on('data', (d) => process.stdout.write('[srv] ' + d));
server.stderr.on('data', (d) => process.stdout.write('[srv-err] ' + d));
server.unref();

setTimeout(async () => {
  try {
    const out = execFileSync('node', [path.join(dir, 'test_dynamic.js')], { encoding: 'utf8', timeout: 90000 });
    process.stdout.write(out);
  } catch (e) {
    process.stdout.write((e.stdout || '') + (e.stderr || ''));
    process.exitCode = 1;
  }
  try { process.kill(server.pid, 'SIGTERM'); } catch (e) {}
  process.exit(process.exitCode || 0);
}, 2500);

