const fs = require('fs');
const p = 'C:\\Users\\oyfsh\\Downloads\\沙尘救援3.zip\\沙尘救援3.zip\\沙尘救援3\\server.mjs';
let t = fs.readFileSync(p, 'utf8');

// 1) 改写 runAgentDecision：所有出口附带 log
const oldFn = `function runAgentDecision() {
  const decision = decide(state, true);
  const { step, name, tool, cameraId, reason, blocked, done, act, extra, brightness } = decision;
  if (done) {
    event('agh','decision',\`[步骤\${step}] \${name}：\${reason}\`,{step,tool:null});
    return { decision, executed: null };
  }
  if (blocked) {
    event('agh','blocked',\`[步骤\${step}] \${name}：\${reason}\`,{step,tool});
    return { decision, executed: null };
  }
  if (!tool) {
    event('agh','decision',\`[步骤\${step}] \${name}：\${reason}\`,{step,tool:null});
    return { decision, executed: null };
  }
  const body = cameraId ? { cameraId } : {};
  if (brightness !== undefined) body.brightness = brightness;
  // 观察类：纯读取，作为决策证据记录
  if (observeTools.includes(tool)) {
    let obsData;
    try { obsData = action(tool,'agh', body ).data; }
    catch(e) { obsData = { error: e.message }; }
    event('agh','observe',\`[步骤\${step}] \${name}：\${reason} → 观测\${cameraId?' '+cameraId:''}\`,{step,tool,cameraId,data:obsData});
    state.connection.lastAgentEvent = new Date().toISOString();
    return { decision, executed: [{ tool, result: obsData }] };
  }
  // 动作类：执行工具，再执行伴随动作 extra
  const executed = [];
  try {
    executed.push({ tool, result: action(tool,'agh', body) });
    event('agh','decision',\`[步骤\${step}] \${name}：\${reason} → 已执行 \${tool}\`,{step,tool});
  } catch(e) {
    state.metrics.failedToolCalls++;
    event('agh','rejected',\`[步骤\${step}] \${name}：\${reason} → \${tool} 被拒（\${e.message}）\`,{step,tool});
    executed.push({ tool, error: e.message });
  }
  if (Array.isArray(extra)) {
    for (const ex of extra) {
      try { executed.push({ tool: ex.tool, result: action(ex.tool,'agh', ex) }); }
      catch(e2) { state.metrics.failedToolCalls++; executed.push({ tool: ex.tool, error: e2.message }); }
    }
  }
  state.connection.lastAgentEvent = new Date().toISOString();
  return { decision, executed };
}`;

const newFn = `function runAgentDecision() {
  const decision = decide(state, true);
  const { step, name, tool, cameraId, reason, blocked, done, act, extra, brightness } = decision;
  // 结果标记：决定 log.result
  let result;
  if (done) result = 'completed';
  else if (blocked) result = 'blocked';
  else if (!tool) result = 'accepted';
  else result = 'accepted';
  if (done) {
    event('agh','decision',\`[步骤\${step}] \${name}：\${reason}\`,{step,tool:null});
    const log = buildAgenticLog(decision, result);
    return { decision, executed: null, log };
  }
  if (blocked) {
    event('agh','blocked',\`[步骤\${step}] \${name}：\${reason}\`,{step,tool});
    const log = buildAgenticLog(decision, result);
    return { decision, executed: null, log };
  }
  if (!tool) {
    event('agh','decision',\`[步骤\${step}] \${name}：\${reason}\`,{step,tool:null});
    const log = buildAgenticLog(decision, result);
    return { decision, executed: null, log };
  }
  const body = cameraId ? { cameraId } : {};
  if (brightness !== undefined) body.brightness = brightness;
  // 观察类：纯读取，作为决策证据记录
  if (observeTools.includes(tool)) {
    let obsData;
    try { obsData = action(tool,'agh', body ).data; result = 'observed'; }
    catch(e) { obsData = { error: e.message }; result = 'rejected'; }
    event('agh','observe',\`[步骤\${step}] \${name}：\${reason} → 观测\${cameraId?' '+cameraId:''}\`,{step,tool,cameraId,data:obsData});
    state.connection.lastAgentEvent = new Date().toISOString();
    const log = buildAgenticLog(decision, result);
    return { decision, executed: [{ tool, result: obsData }], log };
  }
  // 动作类：执行工具，再执行伴随动作 extra
  const executed = [];
  let rejected = false;
  try {
    executed.push({ tool, result: action(tool,'agh', body) });
    event('agh','decision',\`[步骤\${step}] \${name}：\${reason} → 已执行 \${tool}\`,{step,tool});
  } catch(e) {
    rejected = true; state.metrics.failedToolCalls++;
    event('agh','rejected',\`[步骤\${step}] \${name}：\${reason} → \${tool} 被拒（\${e.message}）\`,{step,tool});
    executed.push({ tool, error: e.message });
  }
  if (Array.isArray(extra)) {
    for (const ex of extra) {
      try { executed.push({ tool: ex.tool, result: action(ex.tool,'agh', ex) }); }
      catch(e2) { state.metrics.failedToolCalls++; rejected = true; executed.push({ tool: ex.tool, error: e2.message }); }
    }
  }
  result = rejected ? 'rejected' : 'accepted';
  state.connection.lastAgentEvent = new Date().toISOString();
  const log = buildAgenticLog(decision, result);
  return { decision, executed, log };
}`;

if (!t.includes(oldFn)) { console.log('old runAgentDecision not found verbatim'); process.exit(1); }
t = t.replace(oldFn, newFn);

// 2) 加 GET /api/agent/logs 端点
const routeAnchor = "if (req.method === 'GET' && url.pathname === '/api/agent/state')";
if (t.includes("'/api/agent/logs'")) { console.log('logs endpoint already present'); }
else {
  const logsRoute = "if (req.method === 'GET' && url.pathname === '/api/agent/logs') return respond(200,{logs:agentLogs});\n    " + routeAnchor;
  t = t.replace(routeAnchor, logsRoute);
}

fs.writeFileSync(p, t);
console.log('runAgentDecision now emits AGH log; /api/agent/logs added');

