// 验证结构化 AGH 日志格式
// 每条日志必须含: observation, decision, tool, result, next
const base = 'http://127.0.0.1:8787';
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

let passed = 0, failed = 0;
function assert(cond, msg) { if (cond) { passed++; console.log('  PASS  ' + msg); } else { failed++; console.log('  FAIL  ' + msg); } }

(async () => {
  await fetch(base + '/api/control', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ reset: true }) });

  // 跑完整链路
  for (let i = 0; i < 60; i++) {
    const r = await fetch(base + '/api/agent/decide', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: '{}' });
    const d = await r.json();
    if (d.state.phase === 'completed') break;
    await sleep(1000);
  }

  // 取完整日志
  const logsResp = await (await fetch(base + '/api/agent/logs')).json();
  const logs = logsResp.logs;
  console.log('共 ' + logs.length + ' 条 AGH 日志。');
  if (logs.length === 0) { console.log('FAIL: 无日志'); process.exit(1); }

  // 1) 字段完整性
  const required = ['timestamp', 'step', 'observation', 'decision', 'tool', 'result', 'next'];
  let allHaveFields = true;
  for (const l of logs) {
    for (const f of required) {
      if (!(f in l)) { allHaveFields = false; console.log('  缺字段 ' + f + ' 于 log step' + l.step + ': ' + JSON.stringify(l).slice(0, 120)); }
    }
  }
  assert(allHaveFields, '所有日志均含 observation/decision/tool/result/next 字段');

  // 2) observation 格式
  const obsOk = logs.every((l) => /^visibility=\d+m, wind=/.test(l.observation));
  assert(obsOk, 'observation 均形如 "visibility=XXm, wind=YYm/s"');

  // 3) result 取值集合
  const results = [...new Set(logs.map((l) => l.result))];
  const valid = new Set(['accepted', 'rejected', 'observed', 'blocked', 'completed']);
  assert(results.every((x) => valid.has(x)), 'result 取值均在合法集合内: ' + JSON.stringify(results));

  // 4) next 非空字符串
  assert(logs.every((l) => typeof l.next === 'string' && l.next.length > 0), 'next 均为非空字符串');

  // 5) 展示首/中/尾各一条
  console.log('\n--- 样例（首条） ---');
  console.log(JSON.stringify(logs[0], null, 2));
  console.log('\n--- 样例（含 dispatch_drone 的那条） ---');
  const dispatch = logs.find((l) => l.tool === 'dispatch_drone');
  console.log(dispatch ? JSON.stringify(dispatch, null, 2) : '（未出现 dispatch_drone 工具日志）');
  console.log('\n--- 样例（末条） ---');
  console.log(JSON.stringify(logs[logs.length - 1], null, 2));

  console.log('\n=== 汇总: 通过 ' + passed + ' / 失败 ' + failed + ' ===');
  process.exit(failed ? 1 : 0);
})().catch((e) => { console.error('error:', e); process.exit(2); });

