// demo_autonomous.js — 完整自主演示：按 7 阶段推进（phase 驱动），打印每步 AGH 结构化日志
// 依赖服务运行于 127.0.0.1:8787（由 runner.js 启动）
const base = 'http://127.0.0.1:8787';
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function control(body) {
  const r = await fetch(base + '/api/control', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) });
  return r.json();
}
async function decide() {
  const r = await fetch(base + '/api/agent/decide', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: '{}' });
  return r.json();
}
async function getState() {
  const r = await fetch(base + '/api/state');
  return (await r.json()).state;
}
async function logs() {
  return (await (await fetch(base + '/api/agent/logs')).json()).logs;
}

function hr(t) { console.log('\n' + '='.repeat(64) + '\n## ' + t + '\n' + '='.repeat(64)); }
function showLog(l) {
  console.log('  step' + String(l.step).padEnd(2) + ' ' + l.result.padEnd(9) + ' tool=' + String(l.tool).padEnd(22) + 'next=' + l.next);
  console.log('     obs: ' + l.observation);
  console.log('     why: ' + l.decision);
}
// 每轮推进：调用一次 decide 并打印 log（仅打印“动作类”步骤，观察类略过以精简）
async function step(verbose) {
  const d = await decide();
  if (d.log && verbose) showLog(d.log);
  return d;
}

(async () => {
  await control({ reset: true });
  await control({ level: 2 }); // vis 383m, wind 9.6 —— 全程安全阈值内

  hr('阶段 1：读取气象站');
  let d = await step(true);
  // 阶段 2：判断车辆（step3 自救 accepted 会执行）
  hr('阶段 2：判断车辆状态 → 尝试自救');
  showLog(d.log);

  hr('阶段 3：自救失败 → 停止车辆');
  // 自救 5s 后自动失败（v.status 回 stuck），agent 随后 stop_vehicle
  let stopped = false;
  for (let i = 0; i < 12 && !stopped; i++) {
    d = await step(false);
    if (d.log.step === 4) { showLog(d.log); stopped = true; }
    else if (d.log.result === 'blocked') { showLog(d.log); break; }
    await sleep(1000);
  }

  hr('阶段 4：启动无人机侦察');
  let droneOut = false;
  for (let i = 0; i < 40 && !droneOut; i++) {
    d = await step(false);
    if (d.log.step === 6 && d.log.result === 'accepted') { showLog(d.log); droneOut = true; break; }
    if (d.log.step === 7) { if (i % 5 === 0) showLog(d.log); } // 读无人机摄像头
    await sleep(1000);
  }

  hr('阶段 5：获取备用路线（无人机确认）');
  let routeConfirmed = false;
  for (let i = 0; i < 40 && !routeConfirmed; i++) {
    d = await step(false);
    const s = await getState();
    if (s.route.known) {
      if (!routeConfirmed) { showLog(d.log); routeConfirmed = true; }
      break;
    }
    if (i % 5 === 0) showLog(d.log);
    await sleep(1000);
  }
  if (routeConfirmed) console.log('  ✓ 路线已确认：' + (await getState()).route.name + '，可通行');

  hr('阶段 6：派遣救援车辆（前设诱导屏"前方救援，限速 30"）');
  let rescueOut = false;
  for (let i = 0; i < 60 && !rescueOut; i++) {
    d = await step(false);
    if (d.log.step === 9 && !rescueOut) showLog(d.log); // 开灯+改诱导弹
    if (d.log.step === 10 && d.log.result === 'accepted') { showLog(d.log); rescueOut = true; break; }
    if (i % 5 === 0) showLog(d.log); // 读救援摄像头
    await sleep(1000);
  }

  hr('阶段 7：接收救援成功反馈');
  let done = false;
  for (let i = 0; i < 60 && !done; i++) {
    d = await step(false);
    if (d.log.result === 'completed') { showLog(d.log); done = true; break; }
    if (i % 5 === 0) showLog(d.log);
    await sleep(1000);
  }

  const final = await getState();
  console.log('\n  最终状态: phase=' + final.phase + '  success=' + final.metrics.success);
  console.log('  指标: agentToolCalls=' + final.metrics.agentToolCalls + '  failedToolCalls=' + final.metrics.failedToolCalls + '  manualInterventions=' + final.metrics.manualInterventions + '  duration=' + final.elapsed + 's');

  hr('完整 AGH 日志（按时间顺序）');
  const all = await logs();
  all.forEach((l, i) => {
    console.log('  [' + String(i).padStart(2) + '] ' + l.result.padEnd(9) + ' step' + String(l.step).padEnd(2) + '  ' + JSON.stringify({ observation: l.observation, decision: l.decision, tool: l.tool, result: l.result, next: l.next }));
  });

  console.log('\n=== 自主演示' + (done && final.metrics.success ? '成功' : '未完成') + ' ===');
  process.exit(done && final.metrics.success ? 0 : 1);
})().catch((e) => { console.error('demo error:', e); process.exit(2); });

// demo_autonomous.js — 完整自主演示：顺序驱动 decide 至完成，再按 7 阶段聚合展示 AGH 日志
// 依赖服务运行于 127.0.0.1:8787（由 runner.js 启动）
const base = 'http://127.0.0.1:8787';
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function control(body) {
  const r = await fetch(base + '/api/control', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body) });
  return r.json();
}
async function decide() {
  const r = await fetch(base + '/api/agent/decide', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: '{}' });
  return r.json();
}
async function logs() {
  return (await (await fetch(base + '/api/agent/logs')).json()).logs;
}
function hr(t) { console.log('\n' + '='.repeat(64) + '\n## ' + t + '\n' + '='.repeat(64)); }
function showLog(l) {
  console.log('  step' + String(l.step).padEnd(2) + ' ' + l.result.padEnd(9) + ' tool=' + String(l.tool).padEnd(22) + 'next=' + l.next);
  console.log('     obs: ' + l.observation);
