}

(async () => {
  await control({ reset: true });
  await control({ level: 2 }); // vis 383m, wind 9.6 —— 全程安全阈值内

  // 顺序驱动：反复 decide 直到 completed。每轮只取“动作类”日志（跳过重复观察类）
  const trail = []; // 记录 (log, state)
  let done = false;
  for (let i = 0; i < 120 && !done; i++) {
    const d = await decide();
    const l = d.log;
    // 记录每轮，但“观察类”只在阶段切换时记录一次（避免刷屏）
    if (l.result !== 'observed' || i === 0 || (i > 0 && trail[trail.length - 1].log.step !== l.step)) {
      trail.push({ log: l, state: d.state });
    }
    if (l.result === 'completed') done = true;
    await sleep(700); // 比模拟 tick(1s) 略快，让驱动主导节奏
  }

  const final = (await logs()); // logs
  const last = trail[trail.length - 1];

  // 按 7 阶段聚合展示（同一 step 只取第一次出现的日志）
  const byStep = {};
  for (const t of trail) { if (!(t.log.step in byStep)) byStep[t.log.step] = t.log; }

  hr('阶段 1：读取气象站');
  showLog(byStep[1] || byStep[3]);

  hr('阶段 2：判断车辆状态');
  console.log('  车辆状态: stuck=' + (last ? last.state.vehicle.stuck : '?') + '  能见度 ' + (byStep[3] ? byStep[3].observation : ''));

  hr('阶段 3：停止或尝试自救');
  showLog(byStep[3] || byStep[4]);

  hr('阶段 4：启动无人机');
  showLog(byStep[6] || byStep[7]);

  hr('阶段 5：获取备用路线');
  const routeLog = byStep[8] || byStep[7];
  showLog(routeLog);
  console.log('  ✓ 路线: ' + (last ? last.state.route.name : '?') + '（可通行）');

  hr('阶段 6：派遣救援车辆');
  const rescueLog = byStep[10] || byStep[9];
  showLog(rescueLog);

  hr('阶段 7：接收救援成功反馈');
  const doneLog = byStep[12] || trail[trail.length - 1].log;
  showLog(doneLog);

  const s = last.state;
  console.log('\n  最终: phase=' + s.phase + '  success=' + s.metrics.success);
  console.log('  指标: agentToolCalls=' + s.metrics.agentToolCalls + '  failed=' + s.metrics.failedToolCalls + '  manual=' + s.metrics.manualInterventions + '  用时=' + s.elapsed + 's');
  console.log('  诱导弹: "' + s.vms.message + '"  补光灯: ' + (s.light.on ? '开启 ' + s.light.brightness + '%' : '关闭'));

  hr('完整 AGH 日志（' + final.length + ' 条，按时间顺序）');
  final.forEach((l, i) => {
    console.log('  [' + String(i).padStart(2) + '] ' + l.result.padEnd(9) + ' step' + String(l.step).padEnd(2) + '  ' + JSON.stringify({ observation: l.observation, decision: l.decision, tool: l.tool, result: l.result, next: l.next }));
  });

  console.log('\n=== 自主演示' + (done && s.metrics.success ? '成功 ✓' : '未完成 ✗') + ' ===');
  process.exit(done && s.metrics.success ? 0 : 1);
})().catch((e) => { console.error('demo error:', e); process.exit(2); });

