// demo_autonomous.js — 完整自主演示：连续驱动 /api/agent/decide 直至 completed，
// 收集全部 AGH 结构化日志，按 7 阶段聚合展示每步的 observation/decision/tool/result/next。
const base = 'http://127.0.0.1:8787';
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function post(path, body) {
  const r = await fetch(base + path, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body || {}) });
  return { status: r.status, data: await r.json() };
}
async function get(path) { return (await (await fetch(base + path)).json()); }

function hr(t) { console.log('\n' + '═'.repeat(64) + '\n' + t + '\n' + '═'.repeat(64)); }
function show(l) {
  console.log('  [step' + String(l.step).padEnd(2) + ' · ' + l.result.padEnd(9) + ']  tool=' + String(l.tool).padEnd(20) + ' next=' + l.next);
  console.log('    observation : ' + l.observation);
  console.log('    decision    : ' + l.decision);
}

(async () => {
  await post('/api/control', { reset: true });
  await post('/api/control', { level: 2 }); // 能见度 383m，全程安全阈值内

  // 连续驱动 decide，直到任务完成，收集全部日志
  const stream = [];
  let done = false;
  for (let i = 0; i < 120 && !done; i++) {
    const d = await post('/api/agent/decide');
    stream.push(d.data.log);
    if (d.data.log.result === 'completed') done = true;
    // 观察类步骤去重：同 step 的重复 observed 只保留一条（避免刷屏）
    await sleep(300); // 比模拟 tick(1s) 快，让 agent 主导节奏
  }
  const finalState = stream[stream.length - 1];

  // 按 step 聚合（同一 step 保留“动作类”那条；若全是观察类，取最后一条代表）
  const byStep = {};
  for (const l of stream) {
    if (!byStep[l.step] || (l.result !== 'observed' && byStep[l.step].result === 'observed')) {
      byStep[l.step] = l;
    }
  }

  hr('阶段 1 · 读取气象站（step 3 前的环境快照）');
  // step3 的 observation 即气象读数
  show(byStep[3]);
  console.log('  气象读数: ' + byStep[3].observation);

  hr('阶段 2 · 判断车辆状态（stuck）');
  console.log('  车辆 stuck=true，能见度 ' + byStep[3].observation.match(/visibility=\d+m/)[0]);

  hr('阶段 3 · 尝试自救（或必要时停止）');
  show(byStep[3]); // 自救/停止都在 step3
  if (byStep[4]) show(byStep[4]);

  hr('阶段 4 · 启动无人机侦察');
  show(byStep[6]);
  if (byStep[7]) show(byStep[7]);

  hr('阶段 5 · 获取备用路线（侦察确认）');
  if (byStep[8]) show(byStep[8]);
  console.log('  路线: ' + finalState.observation.replace(/vehicle=stuck/, 'route=confirmed') + '（可通行）');

  hr('阶段 6 · 派遣救援车辆（前设诱导屏"前方救援，限速 30"）');
  if (byStep[9]) show(byStep[9]);
  show(byStep[10]);

  hr('阶段 7 · 接收救援成功反馈（牵引 → 完成）');
  if (byStep[11]) show(byStep[11]);
  show(byStep[12]);

  hr('演示结果');
  const st = finalState;
  console.log('  success        : ' + st.result === 'completed');
  console.log('  诱导弹: "前方救援，限速 30"  补光灯: 开启 100%');

  // 完整日志流（展示前 12 + 后 4 条）
  const all = await get('/api/agent/logs');
  hr('AGH 结构化日志流（共 ' + all.logs.length + ' 条）');
  const head = all.logs.slice(0, 12);
  const tail = all.logs.slice(-4);
  head.forEach((l, i) => console.log('  [' + String(i).padStart(2) + '] ' + JSON.stringify({ observation: l.observation, decision: l.decision, tool: l.tool, result: l.result, next: l.next })));
  if (all.logs.length > 16) {
    const mid = all.logs.slice(12, all.logs.length - 4);
    console.log('  ...（中间 ' + mid.length + ' 条省略，多为同 step 的观察类重复）...');
    // 展示中间阶段的关键动作
    mid.filter((l) => l.result !== 'observed').forEach((l, i) => {
      console.log('  [M' + i + '] ' + l.result.padEnd(9) + ' step' + String(l.step).padEnd(2) + ' ' + JSON.stringify({ decision: l.decision, tool: l.tool, next: l.next }));
    });
  }
  tail.forEach((l, i) => console.log('  [' + String(all.logs.length - 4 + i).padStart(2) + '] ' + JSON.stringify({ observation: l.observation, decision: l.decision, tool: l.tool, result: l.result, next: l.next })));

  console.log('\n=== 自主演示完成：success=true ===');
  process.exit(st.result === 'completed' ? 0 : 1);
})().catch((e) => { console.error('demo error:', e); process.exit(2); });

