1	// agent.mjs — 基础决策顺序引擎 + 动态变化响应（C 的 AGH 接入前，由仿真驱动演示）
2	// 导出 DECISION_PLAN（12 步声明）与 decide(state, apply) 判定器。
3	// 每步返回 { step, kind: observe|judge|act, tool?, extra?, blocked?, done?, reason }。
4	
5	const limits = {
6	  selfRecovery: { minVisibility: 150 },
7	  drone: { maxWind: 12, minVisibility: 150, minBattery: 20 },
8	  rescue: { minVisibility: 100 },
9	};
10	
11	// 路线是否已确认可通行
12	export const routeReady = (s) => Boolean(s.route.known && s.route.traversable);
13	// 路线是否"已知但不可通行"（触发封闭绕行）
14	export const routeBlocked = (s) => Boolean(s.route.known && !s.route.traversable);
15	
16	// 12 步基础决策顺序（顺序即任务推进序）
17	export const DECISION_PLAN = [
18	  { step: 1, name: '读取气象站状态', kind: 'observe', tool: 'get_weather_station_status' },
19	  { step: 2, name: '读取车辆状态', kind: 'observe', tool: 'get_vehicle_status' },
20	  { step: 3, name: '判断车辆能否自救', kind: 'judge', tool: 'attempt_self_recovery' },
21	  { step: 4, name: '必要时停止车辆', kind: 'act', tool: 'stop_vehicle' },
22	  { step: 5, name: '判断无人机能否起飞', kind: 'judge', tool: 'dispatch_drone' },
23	  { step: 6, name: '派遣无人机侦察', kind: 'act', tool: 'dispatch_drone' },
24	  { step: 7, name: '读取无人机摄像头', kind: 'observe', tool: 'get_camera_frame' },
25	  { step: 8, name: '确认备用路线', kind: 'judge', tool: 'return_drone' },
26	  { step: 9, name: '设置补光灯与诱导屏', kind: 'act', tool: 'turn_light_on' },
27	  { step: 10, name: '派遣救援车', kind: 'act', tool: 'dispatch_rescue_vehicle' },
28	  { step: 11, name: '读取救援车摄像头', kind: 'observe', tool: 'get_camera_frame' },
29	  { step: 12, name: '完成牵引', kind: 'observe', tool: 'get_camera_frame' },
30	];
31	
32	// 诱导屏文案随情境选择
33	const VMS = {
34	  rescueDispatch: { message: '前方救援，限速 30', limit: 30 },
35	  closedDetour: { message: '前方封闭，请绕行', limit: null },
36	  sandstorm: { message: '前方沙尘 注意减速', limit: 40 },
37	};
38	
39	// decide：给定当前快照，返回本轮该执行的"下一个有意义动作"。
40	export function decide(state, apply = false) {
41	  const { weather: w, vehicle: v, drone: d, rescueVehicle: r } = state;
42	  const vmsId = state.vms.id;
43	
44	  if (state.phase === 'completed') {
45	    return { step: 12, name: '完成牵引', done: true, reason: '车辆已安全转移，任务完成。', tool: null };
46	  }
47	
48	  const canSelf = v.stuck && w.visibility >= limits.selfRecovery.minVisibility;
49	  const droneOk = w.windSpeed <= limits.drone.maxWind && w.visibility >= limits.drone.minVisibility && d.battery >= limits.drone.minBattery;
50	  const rescueOk = w.visibility >= limits.rescue.minVisibility;
51	  const lowVisibility = w.visibility < limits.rescue.minVisibility; // <100m 需补光
52	
53	  // 路线已确认且可通行、处于救援准备阶段（救援车仍 standby）
54	  const inRescuePrep = routeReady(state) && r.status === 'standby';
55	
56	  // 动态响应 A：能见度过低 → 打开补光灯（仅在救援准备阶段，避免抢占无人机判断）
57	  // 仅当诱导屏尚未显示其它情境文案时才设砂尘提示（避免覆盖"前方救援""绕行"）
58	  if (inRescuePrep && lowVisibility && !state.light.on && state.vms.message === '') {
59	    return apply
60	      ? { step: 9, name: '设置补光灯与诱导屏', act: true, tool: 'turn_light_on', brightness: 100,
61	          extra: [{ tool: 'set_message', deviceId: vmsId, message: VMS.sandstorm.message },
62	                  { tool: 'set_speed_limit', deviceId: vmsId, limit: VMS.sandstorm.limit }],
63	          reason: '能见度 ' + w.visibility + 'm<100，救援前打开补光灯并提示注意减速。' }
64	      : { step: 9, name: '设置补光灯与诱导屏', tool: 'turn_light_on',
65	          extra: [{ tool: 'set_message', deviceId: vmsId
[truncated: 10643 bytes, 164 lines; over the 8192-byte limit; full output stored as artifact 4894dbe13674]
遣救援车。' };
148	    }
149	    return { step: 10, name: '派遣救援车', tool: null, blocked: true, waiting: 'weather',
150	             reason: '能见度 ' + w.visibility + 'm<100，救援车暂缓派遣，等待天气恢复。' };
151	  }
152	
153	  // 救援车在动 → 11. 读救援摄像头
154	  if (r.status === 'enroute' || r.status === 'paused' || r.status === 'towing') {
155	    if (r.status === 'towing') {
156	      return { step: 12, name: '完成牵引', tool: 'get_camera_frame', cameraId: r.camId, reason: '救援车正在牵引被困车辆（tow ' + r.towTime + '/8）。' };
157	    }
158	    return { step: 11, name: '读取救援车摄像头', tool: 'get_camera_frame', cameraId: r.camId,
159	             reason: '救援车' + (r.status === 'enroute' ? '行驶中（' + Math.round(r.progress * 100) + '%）' : '等待天气') + '，读取 ' + r.camId + '。' };
160	  }
161	
162	  // 兜底
163	  return { step: 9, name: '等待', tool: null, reason: '等待下一可行动作。' };
164	}

