// 一次性驱动 4 场景 AGH 工具调用并抓取页面日志/工具调用/结果
const base = 'http://127.0.0.1:8787';
const post = (p, b) => fetch(base + p, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(b) });
const get = (p) => fetch(base + p).then((r) => r.json());

async function driveUntil(completedOnly) {
  let d = await (await post('/api/agent/decide', {})).json();
  let i = 0;
  while (i < 150 && !(completedOnly ? d.log.result === 'completed' : true)) {
    if (!completedOnly) break;
    d = await (await post('/api/agent/decide', {})).json();
    i++;
  }
  return d;
}

(async () => {
  // ===== 场景1 正常 =====
  console.log('\n========== 场景1 正常：AGH 决策→调工具→救援完成 ==========');
  await post('/api/control', { reset: true });
  await post('/api/control', { level: 2 });
  let d = await (await post('/api/agent/decide', {})).json();
  console.log('[AGH决策1] tool=' + d.log.tool + ' result=' + d.log.result + ' next=' + d.log.next);
  console.log('  模型决策: ' + d.log.decision);
  console.log('  observation: ' + d.log.observation);
  // 连续驱动到 completed
  let i = 0;
  while (d.log.result !== 'completed' && i < 150) { d = await (await post('/api/agent/decide', {})).json(); i++; }
  console.log('[AGH完成] step=' + d.log.step + ' result=' + d.log.result + ' 模拟用时=' + d.state.elapsed + 's');
  console.log('[工具调用] agentToolCalls=' + d.state.metrics.agentToolCalls + ' failedToolCalls=' + d.state.metrics.failedToolCalls + ' success=' + d.state.metrics.success);
  let logs = (await get('/api/agent/logs')).logs;
  console.log('[页面AGH日志] 共' + logs.length + '条。末条:');
  console.log('  ' + JSON.stringify(logs[logs.length - 1]));
  console.log('[最终结果] phase=' + d.state.phase + ' 诱导弹="' + d.state.vms.message + '" 补光灯=' + (d.state.light.on ? '开 ' + d.state.light.brightness + '%' : '关'));

  // ===== 场景2 边界 =====
  console.log('\n========== 场景2 边界：等级6 恶劣天气 无人机被阻止 ==========');
  await post('/api/control', { reset: true });
  await post('/api/control', { level: 6 });
  d = await (await post('/api/agent/decide', {})).json();
  console.log('[AGH决策] step=' + d.log.step + ' tool=' + d.log.tool + ' result=' + d.log.result);
  console.log('  模型决策: ' + d.log.decision);
  console.log('  observation: ' + d.log.observation);
  logs = (await get('/api/agent/logs')).logs;
  const blocked = logs.filter((l) => l.result === 'blocked');
  console.log('[页面AGH日志] blocked条目=' + blocked.length + ' 末条:');
  console.log('  ' + JSON.stringify(blocked[blocked.length - 1] || logs[logs.length - 1]));
  console.log('[结果] 无人机被阻止，任务退避等待天气改善（不强行推进）');

  // ===== 场景3 失败 =====
  console.log('\n========== 场景3 失败：工具409后 AGH 如何处理 ==========');
  await post('/api/control', { reset: true });
  await post('/api/control', { level: 6 });
  // 强制调 dispatch_drone → 409
  const r1 = await fetch(base + '/api/tool', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name: 'dispatch_drone' }) });
  const j1 = await r1.json();
  console.log('[工具调用] dispatch_drone → HTTP ' + r1.status + ' 返回: ' + JSON.stringify(j1.toolResult || j1));
  // AGH 侧处理：被拒后 agent 走 blocked 退避
  d = await (await post('/api/agent/decide', {})).json();
  console.log('[AGH处理] 被拒后 agent 决策 step=' + d.log.step + ' result=' + d.log.result + ' tool=' + d.log.tool);
  console.log('  处理: ' + d.log.decision);
  console.log('  next=' + d.log.next + ' （AGH 不强行起飞，退避等待）');

  console.log('\n========== 汇总 ==========');
  console.log('场景1 正常 success=' + (await (await post('/api/control', {})).json()).state.metrics.success);
})();

