// run_normal.js — 正常场景：启动服务 → 模型决策 → AGH 调用工具 → 救援完成
const { spawn } = require('child_process');
const path = require('path');
const dir = 'C:\\Users\\oyfsh\\Downloads\\沙尘救援3.zip\\沙尘救援3.zip\\沙尘救援3';

const base = 'http://127.0.0.1:8787';
const post = (p, b) => fetch(base + p, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(b || {}) });

async function main() {
  // 清理旧服务
  try {
    const { execSync } = require('child_process');
    const out = execSync('netstat -ano | findstr :8787 | findstr LISTENING', { encoding: 'utf8' });
    const pids = out.trim().split(/\n/).map((l) => l.trim().split(/\s+/).pop()).filter((x) => /^\d+$/.test(x));
    pids.forEach((pid) => { try { execSync('taskkill /F /PID ' + pid, { stdio: 'ignore' }); } catch (e) {} });
  } catch (e) {}

  // 启动服务
  const server = spawn('node', [path.join(dir, 'server.mjs')], { detached: true, stdio: ['ignore', 'ignore', 'ignore'], cwd: dir });
  server.unref();

  // 等待健康
  await new Promise((r) => setTimeout(r, 2500));
  let health;
  try {
    health = await (await fetch(base + '/api/state')).json();
    console.log('[启动] 服务已启动 phase=' + health.state.phase + ' tools=' + health.toolNames.length + ' 端口=8787(127.0.0.1)');
  } catch (e) {
    console.log('[启动] 健康检查失败 ' + e.message);
    process.exit(1);
  }

  // 重置 + 等级2
  await post('/api/control', { reset: true });
  await post('/api/control', { level: 2 });
  console.log('[场景] 正常：等级2（能见度383m，风速9.6m/s，全程安全阈值内）');

