// run_boundary.js — 边界场景：恶劣天气（等级6）下无人机被阻止 / 任务等待
const { spawn, execSync } = require('child_process');
const path = require('path');
const dir = 'C:\\Users\\oyfsh\\Downloads\\沙尘救援3.zip\\沙尘救援3.zip\\沙尘救援3';
const base = 'http://127.0.0.1:8787';
const post = (p, b) => fetch(base + p, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(b || {}) });

async function main() {
  // 清理旧服务
  try {
    const out = execSync('netstat -ano | findstr :8787 | findstr LISTENING', { encoding: 'utf8' });
    const pids = out.trim().split(/\n/).map((l) => l.trim().split(/\s+/).pop()).filter((x) => /^\d+$/.test(x));
    pids.forEach((pid) => { try { execSync('taskkill /F /PID ' + pid, { stdio: 'ignore' }); } catch (e) {} });
  } catch (e) {}

  const server = spawn('node', [path.join(dir, 'server.mjs')], { detached: true, stdio: ['ignore', 'ignore', 'ignore'], cwd: dir });
  server.unref();
  await new Promise((r) => setTimeout(r, 2500));

  let health;
  try {
    health = await (await fetch(base + '/api/state')).json();
    console.log('[启动] 服务已启动 phase=' + health.state.phase + ' tools=' + health.toolNames.length + ' 端口=8787(127.0.0.1)');
  } catch (e) {
    console.log('[启动] 健康检查失败 ' + e.message);
    process.exit(1);
  }

  // 边界场景：等级6（能见度 56m，风速 16.8m/s，超过 droneMaxWind=12 且低于 droneMinVisibility=150）
  await post('/api/control', { reset: true });
  await post('/api/control', { level: 6 });
  console.log('[场景] 边界：等级6（能见度56m，风速16.8m/s，超出无人机安全阈值）');

  // 驱动 decide，直到出现 blocked（无人机被阻止 / 任务等待）
  const logs = [];
  let d = null, blocked = false;
  for (let i = 0; i < 30 && !blocked; i++) {
    d = await (await post('/api/agent/decide')).json();
    if (d.log) logs.push(d.log);
    if (d.log && d.log.result === 'blocked') blocked = true;
    await new Promise((r) => setTimeout(r, 600));
  }

  // 强制调一次 dispatch_drone 验证 409 拒绝（失败场景证据，边界场景下也应被阻止）
  const forced = await fetch(base + '/api/tool', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ name: 'dispatch_drone' }) });
  const forcedBody = await forced.json();

  // 抓取页面日志 + 状态
  const allLogs = (await (await fetch(base + '/api/agent/logs')).json()).logs;
  const fin = await (await fetch(base + '/api/state')).json();

  console.log('\n=== 边界场景决策链（全部日志）===');
  logs.forEach((l, i) => {
    console.log('  [' + i + '] step' + String(l.step).padEnd(2) + ' ' + l.result.padEnd(9) + ' tool=' + String(l.tool).padEnd(18) + ' next=' + l.next);
    console.log('     observation: ' + l.observation);
    console.log('     decision    : ' + l.decision);
  });

  console.log('\n=== 强制调 dispatch_drone（验证阻止生效）===');
  console.log('  HTTP ' + forced.status + ' 返回: ' + JSON.stringify(forcedBody.toolResult || forcedBody.error || forcedBody));

  console.log('\n=== 页面 AGH 日志（GET /api/agent/logs，共 ' + allLogs.length + ' 条）===');
  console.log('  末条: ' + JSON.stringify(allLogs[allLogs.length - 1]));

  console.log('\n=== 最终状态 ===');
  console.log('  phase=' + fin.state.phase + '  无人机 status=' + fin.state.drone.status + '  车辆 status=' + fin.state.vehicle.status);
  console.log('  能见度=' + fin.state.weather.visibility + 'm  风速=' + fin.state.weather.windSpeed + 'm/s');
  console.log('  结论: ' + (blocked ? '无人机被阻止（result=blocked），任务退避等待天气改善，不强行推进 ✓' : '警告: 未捕获 blocked，请检查'));

  // 导出
  const fs = require('fs');
  fs.writeFileSync(path.join(dir, 'export', 'agh_logs_boundary.json'), JSON.stringify({ logs: allLogs, forced_dispatch_drone: { http: forced.status, response: forcedBody, rejected: forced.status === 409 } }, null, 2));
  console.log('[导出] export/agh_logs_boundary.json 已更新');

  process.exit(blocked && forced.status === 409 ? 0 : 1);
}

main().catch((e) => { console.error('ERROR', e); process.exit(2); });

