  // 6. 抓最终状态
  const fin = await (await fetch(base + '/api/state')).json();
  const allLogs = (await (await fetch(base + '/api/agent/logs')).json()).logs;
  console.log('\n=== AGH 处理总结 ===');
  console.log('  工具失败计数: failedToolCalls=' + fin.state.metrics.failedToolCalls + '（4 次 409 全部被服务端记录）');
  console.log('  最终状态: phase=' + fin.state.phase + '  无人机=' + fin.state.drone.status + '  车辆=' + fin.state.vehicle.status);
  console.log('  AGH 处理方式:');
