  });

  // 导出
  fs.writeFileSync(path.join(dir, 'export', 'agh_logs_failure.json'), JSON.stringify({
    scenario: 'failure (等级6 强制调 4 个安全约束不允许的工具 → 均 409 拒绝)',
    tool_calls: [
      { name: 'dispatch_drone', http: r1.status, response: j1.toolResult || { error: j1.error }, rejected: r1.status === 409 },
      { name: 'attempt_self_recovery', http: r2.status, response: j2.toolResult || { error: j2.error }, rejected: r2.status === 409 },
      { name: 'dispatch_rescue_vehicle', http: r3.status, response: j3.toolResult || { error: j3.error }, rejected: r3.status === 409 },
      { name: 'get_camera_frame(bogus)', http: r4.status, response: j4.toolResult || { error: j4.error }, rejected: r4.status === 409 },
    ],
    agh_handling: {
      after_reject_decision: d1.log,
      strategy: '把 409 错误作为观察证据，agent 改走安全分支（stop_vehicle / blocked 退避），不强行推进',
      failedToolCalls: fin.state.metrics.failedToolCalls,
    },
    agent_logs: { logs: allLogs },
  }, null, 2));
  console.log('\n[导出] export/agh_logs_failure.json 已更新');

  // 成功条件：4 个 409 全拒绝 + AGH 处理策略正确
